-- Ampliación aditiva C&P. Sin consultas ni escrituras Softland.
CREATE TABLE IF NOT EXISTS cliente_ciclo_comercial (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 ciclo_anterior_id BIGINT UNSIGNED NULL,
 solicitud_origen_id BIGINT UNSIGNED NULL,
 rut_original VARCHAR(20) NOT NULL,
 rut_normalizado VARCHAR(12) NOT NULL,
 codigo_auxiliar_softland VARCHAR(30) NULL,
 usuario_vendedor_id BIGINT NOT NULL,
 vendedor_nombre VARCHAR(255) NOT NULL,
 vendedor_email VARCHAR(254) NOT NULL,
 codigo_vendedor_origen VARCHAR(30) NOT NULL,
 tipo_area ENUM('QUIMICOS','TRAT_AGUA') NOT NULL,
 dias_plazo_inicial SMALLINT UNSIGNED NOT NULL,
 dias_extension SMALLINT UNSIGNED NOT NULL,
 estado ENUM('RESERVADO_BORRADOR','EN_TRAMITE','EN_GESTION','EXTENDIDO','CONVERTIDO','LIBERADO','REASIGNADO') NOT NULL DEFAULT 'RESERVADO_BORRADOR',
 reserva_hasta DATETIME NULL,
 inicio_gestion DATE NULL,
 vence_inicial DATE NULL,
 extension_usada TINYINT(1) NOT NULL DEFAULT 0,
 extension_activada_en DATETIME NULL,
 vence_extension DATE NULL,
 cotizaciones_count INT UNSIGNED NOT NULL DEFAULT 0,
 cotizaciones_otros_count INT UNSIGNED NOT NULL DEFAULT 0,
 ultima_cotizacion_fecha DATE NULL,
 notas_venta_count INT UNSIGNED NOT NULL DEFAULT 0,
 notas_venta_otros_count INT UNSIGNED NOT NULL DEFAULT 0,
 ultima_nota_venta_fecha DATE NULL,
 facturas_count INT UNSIGNED NOT NULL DEFAULT 0,
 facturas_otros_count INT UNSIGNED NOT NULL DEFAULT 0,
 ultima_factura_fecha DATE NULL,
 factura_conversion_folio VARCHAR(50) NULL,
 factura_conversion_fecha DATE NULL,
 factura_conversion_cod_vendedor VARCHAR(30) NULL,
 conversion_detectada_en DATETIME NULL,
 ultima_sincronizacion_softland DATETIME NULL,
 liberado_en DATETIME NULL,
 liberado_motivo VARCHAR(60) NULL,
 liberado_comentario TEXT NULL,
 creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 rut_bloqueado VARCHAR(12) GENERATED ALWAYS AS (CASE WHEN estado IN ('RESERVADO_BORRADOR','EN_TRAMITE','EN_GESTION','EXTENDIDO','CONVERTIDO') THEN NULLIF(rut_normalizado,'') ELSE NULL END) STORED,
 UNIQUE KEY uq_cliente_ciclo_rut_bloqueado (rut_bloqueado),
 KEY idx_ciclo_vendedor_estado (usuario_vendedor_id,estado),
 KEY idx_ciclo_estado_vencimiento (estado,vence_inicial,vence_extension),
 KEY idx_ciclo_codaux (codigo_auxiliar_softland),
 KEY idx_ciclo_sincronizacion (estado,ultima_sincronizacion_softland),
 KEY idx_ciclo_anterior (ciclo_anterior_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS cliente_ciclo_historial (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 ciclo_id BIGINT UNSIGNED NOT NULL,
 accion VARCHAR(50) NOT NULL,
 estado_anterior VARCHAR(30) NULL,
 estado_nuevo VARCHAR(30) NOT NULL,
 usuario_id BIGINT NULL,
 usuario_nombre VARCHAR(255) NOT NULL DEFAULT 'SISTEMA',
 comentario TEXT NULL,
 datos_evento LONGTEXT NULL,
 creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_ciclo_historial (ciclo_id,id),
 KEY idx_ciclo_historial_accion (accion,creado_en)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS cliente_ciclo_alerta (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 ciclo_id BIGINT UNSIGNED NOT NULL,
 tipo VARCHAR(40) NOT NULL,
 fecha_alerta DATE NOT NULL,
 destinatario VARCHAR(254) NOT NULL,
 estado ENUM('PENDIENTE','ENVIADO','ERROR','OMITIDO') NOT NULL DEFAULT 'PENDIENTE',
 intentos SMALLINT UNSIGNED NOT NULL DEFAULT 0,
 ultimo_error VARCHAR(500) NULL,
 creado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 enviado_en DATETIME NULL,
 actualizado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_ciclo_alerta (ciclo_id,tipo),
 KEY idx_alerta_pendiente (estado,fecha_alerta)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

